canonical_compatibility_fixture.source:
#[test]
fn canonical_identity_is_shared_across_adopted_apps_and_history() {
    let id = model::ObjectId(42);
    let writer_id: writer::ObjectId = id;
    let sheets_id: sheets::ObjectId = writer_id;
    let calendar_id: calendar::ObjectId = sheets_id;
    let history_id: history::ObjectId = calendar_id;
    assert_eq!(history_id, id);
    assert_eq!(writer::DocumentId(writer_id).0, sheets_id);
    let actor = history::activity::Actor::new(history::activity::ActorId(7), history::activity::ActorKind::User);
    let writer_actor: writer::Actor = actor;
    assert_eq!(writer_actor, actor);
    let revision: writer::RevisionId = history::activity::RevisionId(3);
    assert_eq!(revision, history::activity::RevisionId(3));
}
